import{_ as r,o as a,c as t,an as o}from"./chunks/framework.CliSN-dr.js";const d=JSON.parse('{"title":"History","description":"","frontmatter":{},"headers":[],"relativePath":"background.md","filePath":"background.md","lastUpdated":null}'),i={name:"background.md"};function n(l,e,s,m,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="History" tabindex="-1">History <a class="header-anchor" href="#History" aria-label="Permalink to &quot;History {#History}&quot;">​</a></h1><p><strong>Beginnings.</strong> Biophysical modelling applies the physics of heat, mass and momentum transfer to organisms (Porter &amp; Gates 1969; Gates 1980). Warren Porter took it up to answer a question about the <a href="https://en.wikipedia.org/wiki/Desert_iguana" target="_blank" rel="noreferrer">desert iguana</a>: what is the thermal advantage of changing colour from dark to light? With mechanical engineers he built a heat budget for the lizard (Porter et al. 1973), a microclimate model of the desert to drive it (Mitchell et al. 1975), and a clear-sky solar radiation model (McCullough &amp; Porter 1971). The same models gave water loss, energy requirements and predator-prey constraints (Porter et al. 1975; Porter &amp; James 1979), and Tracy (1976) extended them to wet-skinned ectotherms such as frogs.</p><p><strong>Endotherms.</strong> For birds and mammals the heat budget is solved for the metabolic or water loss rate that balances it, rather than for body temperature (Porter et al. 1994, 2000).</p><p><strong>Landscapes.</strong> From 1998 the calculations were applied across landscapes (Porter et al. 2002) and developed into mechanistic species distribution models that map the fundamental niche to space (Kearney &amp; Porter 2004, 2009), and compared with correlative approaches (Kearney et al. 2008, 2010b). The suite of microclimate, ectotherm and endotherm models became known as Niche Mapper.</p><p><strong>Dynamic Energy Budgets.</strong> Metabolic, digestive, growth and reproduction rates were at first allometric functions of mass and temperature. Dynamic Energy Budget theory replaced these with an integrated, thermodynamically grounded account of the whole life cycle (Kearney et al. 2010a; Kearney 2012; Kearney et al. 2013).</p><p><strong>NicheMapR.</strong> The Fortran models were given an R interface as <a href="https://github.com/mrke/NicheMapR" target="_blank" rel="noreferrer">NicheMapR</a>: the microclimate model (Kearney &amp; Porter 2017) with soil moisture (Kearney &amp; Maino 2018) and snow (Kearney 2020), the ectotherm and DEB models (Kearney &amp; Porter 2019), the endotherm model (Kearney et al. 2021) and egg and wet-skin water uptake (Kearney &amp; Enriquez-Urzelai 2022).</p><p><strong>NicheMapper.jl.</strong> The Julia ecosystem separates these models into packages with clear interfaces, so each part can be tested, swapped and differentiated on its own; see the <a href="./architecture/mechanistic_niche_modelling_framework">Architecture overview</a>.</p><p>Tests and applications of the NicheMapR models are listed on the <a href="https://mrke.github.io/" target="_blank" rel="noreferrer">NicheMapR website</a>: <a href="https://mrke.github.io/tests/" target="_blank" rel="noreferrer">tests</a> and <a href="https://mrke.github.io/examples/" target="_blank" rel="noreferrer">applications</a>.</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><ul><li><p>Gates, D. M. (1980). <em>Biophysical Ecology</em>. Springer.</p></li><li><p>Kearney, M. (2012). Metabolic theory, life history and the distribution of a terrestrial ectotherm. <em>Functional Ecology</em>, 26, 167–179. <a href="https://doi.org/10.1111/j.1365-2435.2011.01917.x" target="_blank" rel="noreferrer">doi:10.1111/j.1365-2435.2011.01917.x</a></p></li><li><p>Kearney, M. R. (2020). How will snow alter exposure of organisms to cold stress under climate warming? <em>Global Ecology and Biogeography</em>. <a href="https://doi.org/10.1111/geb.13100" target="_blank" rel="noreferrer">doi:10.1111/geb.13100</a></p></li><li><p>Kearney, M. R., Briscoe, N. J., Mathewson, P. D., &amp; Porter, W. P. (2021). NicheMapR – an R package for biophysical modelling: the endotherm model. <em>Ecography</em>, 44, 1595–1605. <a href="https://doi.org/10.1111/ecog.05550" target="_blank" rel="noreferrer">doi:10.1111/ecog.05550</a></p></li><li><p>Kearney, M. R., &amp; Enriquez-Urzelai, U. (2022). A general framework for jointly modelling thermal and hydric constraints on developing eggs. <em>Methods in Ecology and Evolution</em>. <a href="https://doi.org/10.1111/2041-210X.14018" target="_blank" rel="noreferrer">doi:10.1111/2041-210X.14018</a></p></li><li><p>Kearney, M. R., &amp; Maino, J. L. (2018). Can next-generation soil data products improve soil moisture modelling at the continental scale? <em>Journal of Hydrology</em>, 561, 662–673. <a href="https://doi.org/10.1016/j.jhydrol.2018.04.040" target="_blank" rel="noreferrer">doi:10.1016/j.jhydrol.2018.04.040</a></p></li><li><p>Kearney, M., Phillips, B. L., Tracy, C. R., Christian, K., Betts, G., &amp; Porter, W. P. (2008). Modelling species distributions without using species distributions: the cane toad in Australia under current and future climates. <em>Ecography</em>, 31, 423–434. <a href="https://doi.org/10.1111/j.0906-7590.2008.05457.x" target="_blank" rel="noreferrer">doi:10.1111/j.0906-7590.2008.05457.x</a></p></li><li><p>Kearney, M., &amp; Porter, W. P. (2004). Mapping the fundamental niche: physiology, climate, and the distribution of a nocturnal lizard. <em>Ecology</em>, 85, 3119–3131. <a href="https://doi.org/10.1890/03-0820" target="_blank" rel="noreferrer">doi:10.1890/03-0820</a></p></li><li><p>Kearney, M., &amp; Porter, W. P. (2009). Mechanistic niche modelling: combining physiological and spatial data to predict species&#39; ranges. <em>Ecology Letters</em>, 12, 334–350. <a href="https://doi.org/10.1111/j.1461-0248.2008.01277.x" target="_blank" rel="noreferrer">doi:10.1111/j.1461-0248.2008.01277.x</a></p></li><li><p>Kearney, M. R., &amp; Porter, W. P. (2017). NicheMapR – an R package for biophysical modelling: the microclimate model. <em>Ecography</em>, 40, 664–674. <a href="https://doi.org/10.1111/ecog.02360" target="_blank" rel="noreferrer">doi:10.1111/ecog.02360</a></p></li><li><p>Kearney, M. R., &amp; Porter, W. P. (2019). NicheMapR – an R package for biophysical modelling: the ectotherm and Dynamic Energy Budget models. <em>Ecography</em>. <a href="https://doi.org/10.1111/ecog.04680" target="_blank" rel="noreferrer">doi:10.1111/ecog.04680</a></p></li><li><p>Kearney, M., Simpson, S. J., Raubenheimer, D., &amp; Helmuth, B. (2010a). Modelling the ecological niche from functional traits. <em>Philosophical Transactions of the Royal Society B</em>, 365, 3469–3483. <a href="https://doi.org/10.1098/rstb.2010.0034" target="_blank" rel="noreferrer">doi:10.1098/rstb.2010.0034</a></p></li><li><p>Kearney, M. R., Simpson, S. J., Raubenheimer, D., &amp; Kooijman, S. A. L. M. (2013). Balancing heat, water and nutrients under environmental change: a thermodynamic niche framework. <em>Functional Ecology</em>, 27, 950–966. <a href="https://doi.org/10.1111/1365-2435.12020" target="_blank" rel="noreferrer">doi:10.1111/1365-2435.12020</a></p></li><li><p>Kearney, M. R., Wintle, B. A., &amp; Porter, W. P. (2010b). Correlative and mechanistic models of species distribution provide congruent forecasts under climate change. <em>Conservation Letters</em>, 3, 203–213. <a href="https://doi.org/10.1111/j.1755-263X.2010.00097.x" target="_blank" rel="noreferrer">doi:10.1111/j.1755-263X.2010.00097.x</a></p></li><li><p>McCullough, E. C., &amp; Porter, W. P. (1971). Computing clear day solar radiation spectra for the terrestrial ecological environment. <em>Ecology</em>, 52, 1008–1015. <a href="https://doi.org/10.2307/1933806" target="_blank" rel="noreferrer">doi:10.2307/1933806</a></p></li><li><p>Mitchell, J. W., Beckman, W. A., Bailey, R. T., &amp; Porter, W. P. (1975). Microclimatic modeling of the desert. In D. A. De Vries &amp; N. H. Afgan (Eds.), <em>Heat and Mass Transfer in the Biosphere, Part 1</em> (pp. 275–286). Scripta.</p></li><li><p>Porter, W. P., Budaraju, S., Stewart, W. E., &amp; Ramankutty, N. (2000). Calculating climate effects on birds and mammals: impacts on biodiversity, conservation, population parameters, and global community structure. <em>American Zoologist</em>, 40, 597–630. <a href="https://doi.org/10.1093/icb/40.4.597" target="_blank" rel="noreferrer">doi:10.1093/icb/40.4.597</a></p></li><li><p>Porter, W. P., &amp; Gates, D. M. (1969). Thermodynamic equilibria of animals with environment. <em>Ecological Monographs</em>, 39, 227–244. <a href="https://doi.org/10.2307/1948545" target="_blank" rel="noreferrer">doi:10.2307/1948545</a></p></li><li><p>Porter, W. P., &amp; James, F. C. (1979). Behavioral implications of mechanistic ecology II: the African rainbow lizard, <em>Agama agama</em>. <em>Copeia</em>, 1979, 594–619. <a href="https://doi.org/10.2307/1443867" target="_blank" rel="noreferrer">doi:10.2307/1443867</a></p></li><li><p>Porter, W. P., Mitchell, J. W., Beckman, W. A., &amp; DeWitt, C. B. (1973). Behavioral implications of mechanistic ecology: thermal and behavioral modeling of desert ectotherms and their microenvironment. <em>Oecologia</em>, 13, 1–54. <a href="https://doi.org/10.1007/BF00379617" target="_blank" rel="noreferrer">doi:10.1007/BF00379617</a></p></li><li><p>Porter, W. P., Mitchell, J. W., Beckman, W. A., &amp; Tracy, C. R. (1975). Environmental constraints on some predator-prey interactions. In D. M. Gates &amp; R. B. Schmerl (Eds.), <em>Perspectives in Biophysical Ecology</em> (pp. 347–364). Springer.</p></li><li><p>Porter, W. P., Munger, J. C., Stewart, W. E., Budaraju, S., &amp; Jaeger, J. (1994). Endotherm energetics: from a scalable individual-based model to ecological applications. <em>Australian Journal of Zoology</em>, 42, 125–162. <a href="https://doi.org/10.1071/ZO9940125" target="_blank" rel="noreferrer">doi:10.1071/ZO9940125</a></p></li><li><p>Porter, W. P., Sabo, J. L., Tracy, C. R., Reichman, O. J., &amp; Ramankutty, N. (2002). Physiology on a landscape scale: plant-animal interactions. <em>Integrative and Comparative Biology</em>, 42, 431–453. <a href="https://doi.org/10.1093/icb/42.3.431" target="_blank" rel="noreferrer">doi:10.1093/icb/42.3.431</a></p></li><li><p>Tracy, C. R. (1976). A model of the dynamic exchanges of water and energy between a terrestrial amphibian and its environment. <em>Ecological Monographs</em>, 46, 293–326. <a href="https://doi.org/10.2307/1942256" target="_blank" rel="noreferrer">doi:10.2307/1942256</a></p></li></ul>',10)])])}const g=r(i,[["render",n]]);export{d as __pageData,g as default};
